    # Python'un sort() metodu stabildir.
    # Sadece SemVer nesneleriyle karşılaştırma yapabilen bir wrapper kullanıyoruz.
    class SemVerWrapper:
        def __init__(self, v_str):
            self.v = SemVer(v_str)
            self.original = v_str
